import type { CanvasApplication } from "../canvases";
import type { InstalledApplication } from "../installations";
import type { Interface, ResolvedInterfacesOf } from "./applications";
import {
  BrettApplication,
  brandApplicationId,
  type ApplicationId,
} from "./brett-applications";
import type { CoreApp, CoreApplication } from "./core-apps";
import type { Studio, StudioApplication, StudioWorkspace } from "./studios";

/**
 * @public
 */
export type Application =
  | CoreApplication
  | StudioApplication
  | StudioWorkspace
  | CanvasApplication
  | InstalledApplication;

/**
 * @public
 */
export class ApplicationList<TApplication extends Application = Application> {
  readonly applications: TApplication[];

  /**
   * @param applications - The applications to initialize the list with.
   */
  constructor(applications: TApplication[]) {
    this.applications = [...applications];
  }

  toJSON(): (Studio | CoreApp)[] {
    return this.applications.flatMap((application) =>
      application instanceof BrettApplication ? [application.toJSON()] : [],
    );
  }

  /**
   * The applications that belong in a listing (the dock slots, the home tiles).
   * Only `default` applications are listed. Both `unlisted` and `disabled` are
   * kept out of listings; `unlisted` remains openable via {@link findByPath},
   * which doesn't filter on visibility.
   */
  get listed(): TApplication[] {
    return this.applications.filter(
      (application) => application.visibility === "default",
    );
  }

  /** Enables `for...of`, spread and `Array.from` over the list. */
  [Symbol.iterator](): ArrayIterator<TApplication> {
    return this.applications[Symbol.iterator]();
  }

  findApplicationsByType<T extends TApplication["type"]>(
    type: T,
  ): Extract<TApplication, { type: T }>[];
  findApplicationsByType<T extends TApplication["type"][]>(
    types: T,
  ): Extract<TApplication, { type: T[number] }>[];
  findApplicationsByType(
    _type: TApplication["type"] | TApplication["type"][],
  ): TApplication[] {
    const types = Array.isArray(_type) ? _type : [_type];

    return this.applications.filter((r) => types.includes(r.type));
  }

  findApplication(
    type: "canvas",
  ): Extract<TApplication, { type: "canvas" }> | undefined;
  findApplication(
    type: "installation",
    name: string,
  ): Extract<TApplication, { type: "installation" }> | undefined;
  findApplication(
    type: "coreApp",
    id: ApplicationId,
  ): Extract<TApplication, { type: "coreApp" }> | undefined;
  findApplication(
    type: "studio",
    id: ApplicationId,
  ): Extract<TApplication, { type: "studio" }> | undefined;
  findApplication(
    type: "workspace",
    id: string,
  ): Extract<TApplication, { type: "workspace" }> | undefined;
  findApplication(
    type: TApplication["type"],
    id?: ApplicationId | string,
  ): TApplication | undefined {
    switch (type) {
      case "installation":
        return this.applications.find(
          (r) => r.type === "installation" && r.name === id,
        );
      case "canvas":
        return this.applications.find((r) => r.type === type);
      case "coreApp":
      case "studio":
      case "workspace": {
        return this.applications.find((r) => r.type === type && r.id === id);
      }
    }
  }

  /**
   * The one application a location puts in the foreground — canvas by its route,
   * installations by their slug, applications by the id in the URL. `undefined`
   * when nothing matches or the match has no app view (not navigable, e.g. an
   * SDK app that only docks panels).
   */
  findByPath(pathname: string): TApplication | undefined {
    const [root, id] = pathname.split("/").filter(Boolean);
    const application = (() => {
      switch (root) {
        case "canvas":
          return this.findApplication("canvas");
        case "studios":
          return id
            ? this.findApplication("studio", brandApplicationId(id))
            : undefined;
        case "applications":
          return id
            ? this.findApplication("coreApp", brandApplicationId(id))
            : undefined;
        case "local":
          // A local app can share its id with its deployed twin; the /local
          // route always renders the local instance.
          return this.applications.find(
            (candidate) =>
              candidate.isLocal &&
              (candidate.type === "studio" || candidate.type === "coreApp") &&
              candidate.id === id,
          );
        // Any other single segment is a candidate installation slug. Canvas and
        // the id-based roots are handled above, so they never fall through here.
        default: {
          return this.applications.find(
            (candidate) =>
              candidate.type === "installation" &&
              candidate.get("application").slug === root,
          );
        }
      }
    })();

    return application?.hasAppView ? application : undefined;
  }

  /**
   * Every brokered interface across the whole list, flattened into loadable
   * resolved refs — narrowed to the given `type`, or all of them. Delegates to
   * each app's {@link AbstractApplication.resolvedInterfaces}, so a consumer
   * holding the list (e.g. off the `applications.list` bus topic) can discover
   * every `tile` (with its footprint metadata) in the workbench and load each
   * into its own federation instance in one call.
   */
  resolvedInterfaces<T extends Interface["type"] | undefined = undefined>(
    type?: T,
  ): ResolvedInterfacesOf<T> {
    return this.applications.flatMap((application) =>
      application.resolvedInterfaces(type),
    ) as unknown as ResolvedInterfacesOf<T>;
  }

  /**
   * Absence counts as a value, so callers diffing the foregrounded application
   * can compare across the states where nothing is.
   */
  static areApplicationsEqual(
    application1?: Application | null,
    application2?: Application | null,
  ): boolean {
    if (application1 == null || application2 == null) {
      return application1 === application2;
    }

    return application1.id === application2.id;
  }
}
